@CrossOrigin
@RestController
@RequestMapping("/DSP")
public class DSPRestController extends BaseSpringRestController {

	public DSPRestController( DSPService service ) {
		this.service = service;
	}
    /**
     * Handles create a DSP.  if not key provided, calls create, otherwise calls save
     * @param		DSP	dSP
     * @return		DSP 
     */
	@PostMapping("/create")
    public DSP create( @RequestBody(required=true) CreateDSPCommand command ) {
    	DSP entity = null;

		entity = service.createDSP( command );
		LOGGER.info( "Successfully created DSP with Id " + entity.getDSPId()  );

		return entity;
    }

    /**
     * Handles updating a DSP.  if no key provided, calls create, otherwise calls save
     * @param		DSP dSP
     * @return		DSP
     */
	@PutMapping("/update")
    public DSP update( @RequestBody(required=true) UpdateDSPCommand command ) {
		DSP entity = null;

		entity = service.updateDSP(command);
		LOGGER.info( "Successfully updated DSP with Id " + command.getDSPId()  );

		return entity;
	}
 
    /**
     * Handles deleting a DSP entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteDSPCommand command ) {                
		service.delete( command );
		LOGGER.info( "Successfully deleted DSP with Id " + command.getDSPId()  );
	}
	
    /**
     * Handles loading a DSP using a UUID
     * @param		UUID uuid 
     * @return		DSP
     */    
    @GetMapping("/load")
    public DSP load( @RequestParam(required=true) UUID uuid ) {
    	DSP entity = service.getDSP( new DSPFetchOneSummary( uuid ) );

		LOGGER.info( "Successfully loaded DSP with Id " + uuid   );

        return entity;
    }

    /**
     * Handles loading all DSP business objects
     * @return		Set<DSP>
     */
    @GetMapping("/")
    public List<DSP> loadAll() {                
    	List<DSP> dSPList = null;

		dSPList = service.getAllDSP();
		LOGGER.info( "successfully loaded all DSPs" );

        return dSPList;
                            
    }


    /**
     * save AdAccounts on DSP
     * @param		command AssignAdAccountsToDSPCommand
     */     
	@PutMapping("/addToAdAccounts")
	public void addToAdAccounts( @RequestBody(required=true) AssignAdAccountsToDSPCommand command ) {
		service.addToAdAccounts( command );
		LOGGER.info( "Successfully added AdAccounts with Id " + command.getDSPId()  );
	}

    /**
     * remove AdAccounts on DSP
     * @param		command RemoveAdAccountsFromDSPCommand
     */     	
	@PutMapping("/removeFromAdAccounts")
	public void removeFromAdAccounts( 	@RequestBody(required=true) RemoveAdAccountsFromDSPCommand command )
	{		
		service.removeFromAdAccounts( command );
		LOGGER.info( "Successfully removed AdAccounts with Id " + command.getDSPId()  );
	}




//************************************************************************    
// Attributes
//************************************************************************
    protected DSP dSP = null;
	protected DSPService service = null;
    private static final Logger LOGGER = LoggerFactory.getLogger(DSPRestController.class.getName());
    
}
